class Rekening {
  private saldo = 0;
  private riwayat: string[] = [];

  setor(jumlah: number): void {
    if (jumlah <= 0) throw new Error("Jumlah harus positif");
    this.saldo += jumlah;
    this.catat("setor " + jumlah);
  }
  lihatSaldo(): number {
    return this.saldo;
  }
  private catat(teks: string): void {
    this.riwayat.push(teks);
  }
  jumlahTransaksi(): number {
    return this.riwayat.length;
  }
}
const r = new Rekening();
r.setor(50000);
r.setor(25000);
console.log(r.lihatSaldo(), r.jumlahTransaksi());

