class Rekening {
  private saldo = 0;
  constructor(public pemilik: string) {}
  setor(jumlah: number): void {
    if (jumlah <= 0) throw new Error("Jumlah harus positif");
    this.saldo += jumlah;
  }
  tarik(jumlah: number): void {
    if (jumlah > this.saldo) throw new Error("Saldo tidak cukup");
    this.saldo -= jumlah;
  }
  lihatSaldo(): number {
    return this.saldo;
  }
}
const r = new Rekening("Rina");
r.setor(50000);
console.log(r.pemilik, r.lihatSaldo());
r.setor(25000);
console.log(r.pemilik, r.lihatSaldo());
try {
  r.tarik(100000);
} catch (e) {
  if (e instanceof Error) console.log(e.message);
}

