class Stok {
  private jumlah = 0;
  masuk(n: number): void {
    this.jumlah += n;
  }
  keluar(n: number): void {
    if (n > this.jumlah) throw new Error("Stok kurang");
    this.jumlah -= n;
  }
  sisa(): number {
    return this.jumlah;
  }
}
const s = new Stok();
s.masuk(10);
s.keluar(4);
console.log(s.sisa());
try {
  s.keluar(9);
} catch (e) {
  if (e instanceof Error) console.log(e.message);
}
